CREATE OR REPLACE FUNCTION public.stage_p10_executed_entry_reconciliation()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_revision constant text := 'P10_ENTRY_EXECUTION_MONOTONIC_V2';
  v_position_id uuid;
  v_previous_state text;
  v_previous_reason text;
  v_sibling_id uuid;
begin
  if tg_table_name = 'trading_orders' then
    if upper(coalesce(new.purpose, '')) <> 'ENTRY' or coalesce(new.executed_volume, 0) <= 0 then
      return new;
    end if;
    v_position_id := new.position_id;
  elsif tg_table_name = 'exchange_trade_fills' then
    if new.bot_order_id is null or coalesce(new.quantity, 0) <= 0 then
      return new;
    end if;
    select o.position_id into v_position_id
    from public.trading_orders o
    where o.id = new.bot_order_id
      and upper(coalesce(o.purpose, '')) = 'ENTRY';
    if v_position_id is null then return new; end if;
  elsif tg_table_name = 'trading_fills' then
    if new.order_id is null or coalesce(new.volume, 0) <= 0 then return new; end if;
    select o.position_id into v_position_id
    from public.trading_orders o
    where o.id = new.order_id
      and upper(coalesce(o.purpose, '')) = 'ENTRY';
    if v_position_id is null then return new; end if;
  else
    return new;
  end if;

  -- Cheap unlocked precheck avoids taking the global settings lock for normal OPEN fills.
  if not exists (
    select 1 from public.trading_positions p
    where p.id = v_position_id
      and p.strategy_key = 'P10_DONCHIAN_BREAKOUT_E10_SLOW_4R'
      and p.is_paper = false
      and p.state in ('CANCELLED', 'ERROR')
  ) then
    return new;
  end if;

  -- Lock order is settings -> position, matching the live-entry guard. This prevents a
  -- late fill and a new same-market entry from deadlocking each other.
  perform public.latch_p10_entry_safety('P10_ENTRY_RECONCILIATION_REQUIRED');

  select p.state, p.close_reason
  into v_previous_state, v_previous_reason
  from public.trading_positions p
  where p.id = v_position_id
    and p.strategy_key = 'P10_DONCHIAN_BREAKOUT_E10_SLOW_4R'
    and p.is_paper = false
    and p.state in ('CANCELLED', 'ERROR')
  for update;
  if not found then return new; end if;

  select p.id into v_sibling_id
  from public.trading_positions p
  where p.id <> v_position_id
    and p.exchange = (select exchange from public.trading_positions where id = v_position_id)
    and p.market = (select market from public.trading_positions where id = v_position_id)
    and p.state in (
      'ENTRY_PENDING', 'OPEN', 'EXITING', 'RECONCILING',
      'RECONCILIATION_FAILED', 'MANUAL_INTERVENTION_REQUIRED'
    )
  order by p.created_at desc
  limit 1;

  if v_sibling_id is not null then
    update public.trading_positions
    set metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object(
          'reconciliation_phase', 'ENTRY',
          'p10_entry_reconciliation_started_at', now(),
          'p10_entry_reconciliation_source', tg_table_name,
          'p10_entry_reconciliation_revision', v_revision,
          'p10_entry_reconciliation_blocked_by_position_id', v_sibling_id,
          'p10_entry_previous_terminal_state', v_previous_state,
          'p10_entry_previous_close_reason', v_previous_reason
        ),
        updated_at = now()
    where id = v_position_id;
    return new;
  end if;

  begin
    update public.trading_positions
    set state = 'RECONCILING',
        closed_at = null,
        close_reason = null,
        metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object(
          'reconciliation_phase', 'ENTRY',
          'p10_entry_reconciliation_started_at', now(),
          'p10_entry_reconciliation_source', tg_table_name,
          'p10_entry_reconciliation_revision', v_revision,
          'p10_entry_previous_terminal_state', v_previous_state,
          'p10_entry_previous_close_reason', v_previous_reason
        ),
        updated_at = now()
    where id = v_position_id;
  exception
    when unique_violation then
      update public.trading_positions
      set metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object(
            'reconciliation_phase', 'ENTRY',
            'p10_entry_reconciliation_started_at', now(),
            'p10_entry_reconciliation_source', tg_table_name,
            'p10_entry_reconciliation_revision', v_revision,
            'p10_entry_reconciliation_blocked_by_unique_index', true,
            'p10_entry_previous_terminal_state', v_previous_state,
            'p10_entry_previous_close_reason', v_previous_reason
          ),
          updated_at = now()
      where id = v_position_id;
  end;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.trg_adopt_manual_trade_fill()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
 if lower(coalesce(new.exchange, '')) = 'binance_futures' then return new; end if;
 if upper(coalesce(new.source, '')) = 'MANUAL' and upper(coalesce(new.side, '')) = 'BUY' and new.position_id is null and new.bot_order_id is null then perform public.adopt_manual_trade_fill(new.id); end if;
 return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.enforce_futures_fill_order_attribution()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_order public.trading_orders%rowtype;
  v_v17 public.v11_long_regime_orders%rowtype;
  v_v17_position uuid;
  v_position_id uuid;
begin
  if new.exchange <> 'binance_futures' then
    return new;
  end if;

  -- V17 lane first: it is the lane that currently trades this account.
  select o.* into v_v17
  from public.v11_long_regime_orders o
  where o.exchange_order_id is not null
    and o.exchange_order_id = new.exchange_order_id
    and o.symbol = new.market
  order by o.created_at desc
  limit 1;

  if found then
    new.v17_order_id := v_v17.id;
    new.v17_position_id := v_v17.position_id;
    new.client_order_id := coalesce(nullif(new.client_order_id, ''), v_v17.client_order_id);
    -- The legacy FK columns stay null: a V17 id is not a trading_orders id.
    new.bot_order_id := null;
    new.position_id := null;
    new.source := 'AUTOMATED';
    new.accounting_status := case when v_v17.position_id is not null then 'PENDING'
                                  else 'UNMATCHED_INVENTORY' end;
    return new;
  end if;

  -- An exchange-resident stop (V17_NATIVE_STOP) closes the position through
  -- /fapi/v1/algoOrder. The resulting market order carries the algo's actualOrderId and
  -- has no row in v11_long_regime_orders, so the protection journal on the position is
  -- the only link back. Verified against EGLDUSDT order 9678930536 on 2026-09-08.
  if new.exchange_order_id is not null then
    select p.id into v_v17_position
    from public.v11_long_regime_positions p
    where p.symbol = new.market
      and exists (
        select 1
        from jsonb_array_elements(
          coalesce(p.metadata->'exitProtection'->'orders', '[]'::jsonb)) o
        where o->>'actualOrderId' = new.exchange_order_id)
    order by p.updated_at desc
    limit 1;

    if v_v17_position is not null then
      -- No v17_order_id exists for a native stop; the position carries the attribution.
      new.v17_order_id := null;
      new.v17_position_id := v_v17_position;
      new.bot_order_id := null;
      new.position_id := null;
      new.source := 'AUTOMATED';
      new.accounting_status := 'PENDING';
      return new;
    end if;
  end if;

  select o.* into v_order
  from public.trading_orders o
  where o.exchange = 'binance_futures'
    and o.market = new.market
    and o.exchange_order_id is not null
    and o.exchange_order_id = new.exchange_order_id
  order by o.created_at desc
  limit 1;

  if found then
    new.bot_order_id := v_order.id;
    new.position_id := v_order.position_id;
    new.client_order_id := coalesce(nullif(new.client_order_id, ''), v_order.identifier);
    new.source := 'AUTOMATED';
    if new.position_id is not null then
      new.accounting_status := 'PENDING';
    end if;
    return new;
  end if;

  new.bot_order_id := null;
  new.client_order_id := null;
  new.source := 'MANUAL';
  v_position_id := null;

  if upper(coalesce(new.side,'')) = 'SELL'
     and coalesce(new.quantity,0) > 0
     and new.executed_at is not null then

    -- Once a manual fill has been safely attributed, keep that attribution immutable
    -- across later idempotent upserts even after the position has fully closed.
    if tg_op = 'UPDATE'
       and old.position_id is not null
       and old.exchange = 'binance_futures'
       and old.market = new.market
       and old.exchange_trade_id = new.exchange_trade_id then
      select p.id into v_position_id
      from public.trading_positions p
      where p.id = old.position_id
        and p.exchange = 'binance_futures'
        and p.market = new.market
        and coalesce(p.is_paper,false) = false
        and p.opened_at is not null
        and p.opened_at <= new.executed_at
        and (p.closed_at is null or p.closed_at >= new.executed_at)
      limit 1;
    end if;

    -- For a newly supplied Edge position id, require positive linked inventory at
    -- the fill instant. This prevents an unrelated manual sell from being attached.
    if v_position_id is null and new.position_id is not null then
      select p.id into v_position_id
      from public.trading_positions p
      where p.id = new.position_id
        and p.exchange = 'binance_futures'
        and p.market = new.market
        and coalesce(p.is_paper,false) = false
        and p.opened_at is not null
        and p.opened_at <= new.executed_at
        and (p.closed_at is null or p.closed_at >= new.executed_at)
        and coalesce((
          select sum(case when upper(f.side)='BUY' then f.quantity else -f.quantity end)
          from public.exchange_trade_fills f
          where f.exchange='binance_futures'
            and f.position_id=p.id
        ),0) > greatest(
          coalesce((
            select sum(f.quantity)
            from public.exchange_trade_fills f
            where f.exchange='binance_futures'
              and f.position_id=p.id
              and upper(f.side)='BUY'
          ),0) * 1e-7,
          1e-10
        )
      limit 1;
    end if;

    if v_position_id is null then
      perform pg_advisory_xact_lock(hashtext('manual-futures-sell:' || new.market));
      select p.id into v_position_id
      from public.trading_positions p
      where p.exchange = 'binance_futures'
        and p.market = new.market
        and coalesce(p.is_paper,false) = false
        and p.opened_at is not null
        and p.opened_at <= new.executed_at
        and (p.closed_at is null or p.closed_at >= new.executed_at)
        and coalesce((
          select sum(case when upper(f.side)='BUY' then f.quantity else -f.quantity end)
          from public.exchange_trade_fills f
          where f.exchange='binance_futures'
            and f.position_id=p.id
        ),0) > greatest(
          coalesce((
            select sum(f.quantity)
            from public.exchange_trade_fills f
            where f.exchange='binance_futures'
              and f.position_id=p.id
              and upper(f.side)='BUY'
          ),0) * 1e-7,
          1e-10
        )
      order by p.opened_at desc, p.created_at desc
      limit 1;
    end if;
  end if;

  new.position_id := v_position_id;
  -- UNPROVEN_FUTURES_SOURCE_20260908: absence of a bot match does not prove manual ownership.
  if v_position_id is null then
    new.source := 'UNCLASSIFIED';
  end if;
  new.accounting_status := case when v_position_id is not null then 'PENDING' else 'UNMATCHED_INVENTORY' end;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.enqueue_trade_notification_outbox()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_order public.trading_orders%rowtype;
  v_event_type text;
  v_enabled boolean;
  v_started_at timestamptz;
begin
  select enabled, started_at into v_enabled, v_started_at
  from public.trade_notification_settings
  where id = 1;

  if coalesce(v_enabled, false) = false then
    return new;
  end if;

  -- Never generate notifications for historical fills that are merely
  -- reconciled or reclassified after the notification system was enabled.
  if new.executed_at is null or new.executed_at < v_started_at then
    return new;
  end if;

  if new.source <> 'AUTOMATED'
     or new.bot_order_id is null
     or new.position_id is null
     or new.accounting_status <> 'ACCOUNTED' then
    return new;
  end if;

  select * into v_order
  from public.trading_orders
  where id = new.bot_order_id;

  if not found then
    return new;
  end if;

  if new.side = 'BUY' then
    v_event_type := 'BUY';
  elsif new.side = 'SELL' then
    if coalesce(new.inventory_quantity_after, 0) <= 0 then
      v_event_type := 'SELL_CLOSE';
    else
      v_event_type := 'SELL_PARTIAL';
    end if;
  else
    return new;
  end if;

  insert into public.trade_notification_outbox (
    bot_order_id, position_id, exchange, market, side, event_type,
    first_fill_at, last_fill_at, updated_at
  ) values (
    new.bot_order_id, new.position_id, new.exchange, new.market, new.side, v_event_type,
    new.executed_at, new.executed_at, now()
  )
  on conflict (bot_order_id) do update set
    position_id = excluded.position_id,
    exchange = excluded.exchange,
    market = excluded.market,
    side = excluded.side,
    event_type = case
      when public.trade_notification_outbox.event_type = 'SELL_CLOSE' then 'SELL_CLOSE'
      when excluded.event_type = 'SELL_CLOSE' then 'SELL_CLOSE'
      else excluded.event_type
    end,
    first_fill_at = least(public.trade_notification_outbox.first_fill_at, excluded.first_fill_at),
    last_fill_at = greatest(public.trade_notification_outbox.last_fill_at, excluded.last_fill_at),
    updated_at = now();

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.settle_manual_futures_sell_fill_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_pos public.trading_positions%rowtype;
  v_last_sell_at timestamptz;
  v_manual_sell_qty numeric := 0;
  v_buy_qty numeric := 0;
begin
  if lower(coalesce(new.exchange,'')) <> 'binance_futures'
     or upper(coalesce(new.side,'')) <> 'SELL'
     or upper(coalesce(new.source,'')) <> 'MANUAL'
     or new.position_id is null then
    return new;
  end if;

  perform set_config('trading_boooo.allow_closed_rewrite','on',true);
  perform public.settle_futures_position_from_exchange_fills(new.position_id);

  select * into v_pos
  from public.trading_positions
  where id=new.position_id;

  select
    max(f.executed_at) filter (where upper(f.side)='SELL'),
    coalesce(sum(f.quantity) filter (where upper(f.side)='SELL' and upper(coalesce(f.source,''))='MANUAL'),0),
    coalesce(sum(f.quantity) filter (where upper(f.side)='BUY'),0)
  into v_last_sell_at,v_manual_sell_qty,v_buy_qty
  from public.exchange_trade_fills f
  where f.exchange='binance_futures'
    and f.position_id=new.position_id;

  if found and v_pos.state='CLOSED' and v_manual_sell_qty > 0 then
    update public.trading_positions
       set closed_at = coalesce(v_last_sell_at, closed_at),
           close_reason = 'MANUAL_EXCHANGE_SELL',
           metadata = coalesce(metadata,'{}'::jsonb) || jsonb_build_object(
             'display_data_status','MANUAL_EXCHANGE_SELL_RECONCILED',
             'manual_exit_reconciliation', jsonb_build_object(
               'revision','8.0.1-MANUAL-FUTURES-SELL-LEDGER',
               'reconciled_at',now(),
               'manual_sell_quantity',v_manual_sell_qty,
               'exchange_entry_quantity',v_buy_qty,
               'last_manual_sell_at',v_last_sell_at
             )
           ),
           updated_at=now()
     where id=new.position_id;
  end if;

  update public.exchange_trade_fills
     set accounting_status='ACCOUNTED',
         updated_at=now()
   where id=new.id
     and accounting_status is distinct from 'ACCOUNTED';

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.v11_long_regime_enforce_slot_cap()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare
  slot_cap constant int := 3;
  open_count int;
begin
  if new.state is distinct from 'OPEN' then
    return new;
  end if;

  -- Serialise concurrent entries so the count below cannot be raced.
  perform pg_advisory_xact_lock(hashtext('v11_long_regime_slot_cap'));

  select count(*)
    into open_count
    from public.v11_long_regime_positions
   where state = 'OPEN'
     and id is distinct from new.id;

  if open_count >= slot_cap then
    raise exception
      'V11_SLOT_CAP_EXCEEDED: % open positions already, cap is %',
      open_count, slot_cap
      using errcode = '23505';
  end if;

  return new;
end;
$function$
